require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/auto_approval.json
# is AutoApproval.approveNew's answer for every Job state, with and without a
# PR, generated by `lake exe syrus_fixtures auto_approval`. This runs the real
# AutoApprovalRule#approve_after_grader_success! on the same inputs and
# compares, so the proof that auto-approval never approves a Job without a PR
# is about the code as it is.
RSpec.describe "AutoApproval model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/auto_approval.json").read)
  let(:user) { Factories.user }
  let(:repository) { Factories.repository(user: user) }

  before { allow(LandingQueueProcessor).to receive(:try_land!) }

  def grader_step(job)
    workflow = Workflow.create!(job: job, trigger_kind: "initial", agent_provider: job.agent_provider, state: "succeeded")
    Step.create!(workflow: workflow, kind: "grade", state: "succeeded", position: 0)
  end

  it "covers every Job state the model distinguishes, with and without a PR" do
    expect(fixture.fetch("cases").map { |c| [ c.fetch("job_state"), c.fetch("pull_request") ] })
      .to match_array(%w[running implemented approved failed].product([ true, false ]))
  end

  fixture.fetch("cases").each do |example|
    state, pull_request, expected = example.values_at("job_state", "pull_request", "job_state_after")

    it "leaves a #{state} Job #{pull_request ? 'with' : 'without'} a PR #{expected}, as the model does" do
      job = Factories.job_record(user: user, repository: repository, state: state, pr_number: pull_request ? 42 : nil)

      AutoApprovalRule.new(job).approve_after_grader_success!(mode: "if_graders_pass", source: "conformance", grader_step: grader_step(job))

      expect(job.reload.state).to eq(expected)
    end
  end
end
